from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
from hashlib import sha256
import json
source = Path('products/services/nz-gets-offline-data-quote/raw/gets-index.html')
base = 'https://www.gets.govt.nz/ExternalIndex.htm'
class NoticeRows(HTMLParser):
    def __init__(self):
        super().__init__()
        self.row = None
        self.rows = []
    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.row = {'text': [], 'urls': []}
        if self.row is not None and tag == 'a':
            href = dict(attrs).get('href')
            if href:
                url = urljoin(base, href)
                parts = urlsplit(url)
                if parts.scheme == 'https' and parts.hostname == 'www.gets.govt.nz' and parts.path.lower().endswith('/externaltenderdetails.htm'):
                    self.row['urls'].append(url)
    def handle_data(self, data):
        if self.row is not None and data.strip():
            self.row['text'].append(' '.join(data.split()))
    def handle_endtag(self, tag):
        if tag == 'tr' and self.row is not None:
            if self.row['urls']:
                self.rows.append({'text': ' | '.join(self.row['text']), 'urls': list(dict.fromkeys(self.row['urls']))})
            self.row = None
raw = source.read_bytes()
parser = NoticeRows()
parser.feed(raw.decode('utf-8'))
count = len({url for row in parser.rows for url in row['urls']})
result = {'source': base, 'source_sha256': sha256(raw).hexdigest(), 'distinct_notice_links_in_rows': count, 'prior_distinct_link_count': 25, 'coverage': 'Matches prior distinct link count' if count == 25 else 'Incomplete row extraction. Inspect the captured markup before inferring notice coverage.', 'rows': parser.rows}
out = Path('products/services/nz-gets-offline-data-quote/director-notice-rows.json')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
